-- v4.4.6 Oracle additive identity, Portal lease, and Graph posture contract.
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CX_HUMAN_IDENTITIES ADD (MOBILE VARCHAR2(64))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -1430 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CX_REGISTRATION_REQUESTS ADD (MOBILE VARCHAR2(64))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -1430 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CX_REGISTRATION_REQUESTS ADD (REGISTRATION_TOKEN_ID VARCHAR2(128))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -1430 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'ALTER TABLE CX_REGISTRATION_REQUESTS ADD (POLICY_VERSION NUMBER(19,0))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -1430 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_HUMAN_PROFILES (PRINCIPAL_ID VARCHAR2(128) PRIMARY KEY, DISPLAY_NAME VARCHAR2(256) NOT NULL, EMAIL VARCHAR2(320), MOBILE VARCHAR2(64), REMEDIATION_STATE VARCHAR2(32) DEFAULT ''CLEAR'' NOT NULL, REMEDIATION_DUE_AT TIMESTAMP, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, UPDATED_BY VARCHAR2(128), UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_REG_FIELD_POLICIES (POLICY_ID VARCHAR2(128) PRIMARY KEY, FIELD_KEY VARCHAR2(64) NOT NULL, REGISTRATION_CONTEXT VARCHAR2(32) NOT NULL, FIELD_STATE VARCHAR2(16) NOT NULL, VISIBLE CHAR(1) DEFAULT ''Y'' NOT NULL, MUTABLE_AFTER_ACTIVATION CHAR(1) DEFAULT ''Y'' NOT NULL, VALIDATOR_KEY VARCHAR2(128) NOT NULL, NORMALIZATION_KEY VARCHAR2(128) NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, REASON VARCHAR2(2000) NOT NULL, UPDATED_BY VARCHAR2(128) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_REG_FIELD_POLICY UNIQUE(FIELD_KEY,REGISTRATION_CONTEXT), CONSTRAINT CK_CX_REG_FIELD_STATE CHECK(FIELD_STATE IN (''REQUIRED'',''OPTIONAL'',''DISABLED'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_IDENTITY_PLATFORM_POLICIES (POLICY_KEY VARCHAR2(128) PRIMARY KEY, POLICY_VALUE VARCHAR2(4000) NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, REASON VARCHAR2(2000) NOT NULL, UPDATED_BY VARCHAR2(128), UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_HUMAN_REG_TOKENS (TOKEN_ID VARCHAR2(128) PRIMARY KEY, TOKEN_DIGEST VARCHAR2(128) NOT NULL UNIQUE, PURPOSE VARCHAR2(32) DEFAULT ''HUMAN_REGISTRATION'' NOT NULL, SPONSOR_PRINCIPAL_ID VARCHAR2(128) NOT NULL, INTENDED_CONSTRAINTS CLOB DEFAULT ''{}'' NOT NULL, EXPIRES_AT TIMESTAMP NOT NULL, MAX_USES NUMBER(10) DEFAULT 1 NOT NULL, USED_COUNT NUMBER(10) DEFAULT 0 NOT NULL, REVOKED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, REASON VARCHAR2(2000) NOT NULL, CONSTRAINT CK_CX_HRT_PURPOSE CHECK(PURPOSE=''HUMAN_REGISTRATION''), CONSTRAINT CK_CX_HRT_USES CHECK(MAX_USES=1 AND USED_COUNT BETWEEN 0 AND MAX_USES))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_IDENTITY_PROVIDERS (PROVIDER_ID VARCHAR2(128) PRIMARY KEY, PROVIDER_KEY VARCHAR2(128) NOT NULL UNIQUE, ADAPTER_TYPE VARCHAR2(128) NOT NULL, PROTOCOL_TYPE VARCHAR2(64) NOT NULL, ISSUER VARCHAR2(512), TENANT_REFERENCE VARCHAR2(256), ENDPOINTS_JSON CLOB DEFAULT ''{}'' NOT NULL, REDIRECT_ALLOWLIST CLOB DEFAULT ''[]'' NOT NULL, SCOPES_JSON CLOB DEFAULT ''[]'' NOT NULL, CREDENTIAL_REFERENCE VARCHAR2(256), ATTRIBUTE_MAPPING CLOB DEFAULT ''{}'' NOT NULL, REGISTRATION_POLICY VARCHAR2(32) DEFAULT ''APPROVAL'' NOT NULL, CAPABILITY_STATUS VARCHAR2(24) DEFAULT ''UNAVAILABLE'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, STATUS VARCHAR2(24) DEFAULT ''DISABLED'' NOT NULL, UPDATED_BY VARCHAR2(128), UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_EXTERNAL_ID_BINDINGS (BINDING_ID VARCHAR2(128) PRIMARY KEY, PRINCIPAL_ID VARCHAR2(128) NOT NULL, PROVIDER_ID VARCHAR2(128) NOT NULL, PROVIDER_TENANT VARCHAR2(256) NOT NULL, PROVIDER_SUBJECT VARCHAR2(512) NOT NULL, PROVIDER_GLOBAL_SUBJECT VARCHAR2(512), CLAIMS_DIGEST VARCHAR2(128) NOT NULL, CLAIMS_SNAPSHOT CLOB DEFAULT ''{}'' NOT NULL, STATUS VARCHAR2(24) DEFAULT ''PENDING'' NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, FIRST_LOGIN_AT TIMESTAMP, LAST_LOGIN_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT UK_CX_EXT_ID_SUBJECT UNIQUE(PROVIDER_ID,PROVIDER_TENANT,PROVIDER_SUBJECT))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_EXT_LOGIN_TXNS (TRANSACTION_ID VARCHAR2(128) PRIMARY KEY, TRANSACTION_DIGEST VARCHAR2(128) NOT NULL UNIQUE, PROVIDER_ID VARCHAR2(128) NOT NULL, ENTRY VARCHAR2(16) NOT NULL, STATE_DIGEST VARCHAR2(128) NOT NULL, NONCE_DIGEST VARCHAR2(128) NOT NULL, PKCE_REFERENCE VARCHAR2(256), QR_REFERENCE VARCHAR2(512), EXPIRES_AT TIMESTAMP NOT NULL, STATUS VARCHAR2(24) DEFAULT ''STARTED'' NOT NULL, ATTEMPTS NUMBER(10) DEFAULT 0 NOT NULL, CALLBACK_DIGEST VARCHAR2(128), FAILURE_CODE VARCHAR2(128), CONSUMED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CK_CX_EXT_TX_ENTRY CHECK(ENTRY IN (''PORTAL'',''APP'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_PORTAL_CONN_POLICIES (PRINCIPAL_ID VARCHAR2(128) PRIMARY KEY, MAX_CONNECTIONS NUMBER(10) DEFAULT 1 NOT NULL, VERSION NUMBER(19,0) DEFAULT 1 NOT NULL, REASON VARCHAR2(2000) NOT NULL, UPDATED_BY VARCHAR2(128) NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CK_CX_PCP_MAX CHECK(MAX_CONNECTIONS BETWEEN 1 AND 32))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_PORTAL_CONNECTIONS (CONNECTION_ID VARCHAR2(128) PRIMARY KEY, PRINCIPAL_ID VARCHAR2(128) NOT NULL, SESSION_DIGEST VARCHAR2(128) NOT NULL UNIQUE, CLIENT_INSTANCE_DIGEST VARCHAR2(128) NOT NULL, NODE_ID VARCHAR2(128) NOT NULL, STATUS VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, FENCING_TOKEN NUMBER(19) DEFAULT 1 NOT NULL, LEASE_EXPIRES_AT TIMESTAMP NOT NULL, LAST_HEARTBEAT_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, RELEASED_AT TIMESTAMP, RELEASE_REASON VARCHAR2(1000))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IDX_CX_PCONN_PRINCIPAL ON CX_PORTAL_CONNECTIONS(PRINCIPAL_ID,STATUS,LEASE_EXPIRES_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE NOT IN (-955,-1408) THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_PORTAL_PAGE_LEASES (LEASE_ID VARCHAR2(128) PRIMARY KEY, CONNECTION_ID VARCHAR2(128) NOT NULL UNIQUE, SESSION_DIGEST VARCHAR2(128) NOT NULL UNIQUE, PAGE_INSTANCE_DIGEST VARCHAR2(128) NOT NULL, FENCING_TOKEN NUMBER(19) DEFAULT 1 NOT NULL, STATUS VARCHAR2(24) DEFAULT ''ACTIVE'' NOT NULL, LEASE_EXPIRES_AT TIMESTAMP NOT NULL, LAST_HEARTBEAT_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE CX_GRAPH_CAP_POSTURE (CAPABILITY_KEY VARCHAR2(128) PRIMARY KEY, POSTURE VARCHAR2(24) NOT NULL, EVIDENCE_ID VARCHAR2(256), IMPLEMENTATION_VERSION VARCHAR2(64), LIMITATION_TEXT VARCHAR2(2000), EDITION_SCOPE VARCHAR2(64) DEFAULT ''ALL'' NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT CK_CX_GCP_POSTURE CHECK(POSTURE IN (''PRODUCTION'',''CONTROLLED'',''DISABLED'',''UNAVAILABLE'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
MERGE INTO CX_IDENTITY_PLATFORM_POLICIES d USING (SELECT 'human_registration_token_required' k,'false' v FROM DUAL) s ON(d.POLICY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(POLICY_KEY,POLICY_VALUE,REASON) VALUES(s.k,s.v,'v4.4.6 default preserves existing registration behavior');
MERGE INTO CX_IDENTITY_PLATFORM_POLICIES d USING (SELECT 'portal_connection_platform_max' k,'8' v FROM DUAL) s ON(d.POLICY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(POLICY_KEY,POLICY_VALUE,REASON) VALUES(s.k,s.v,'v4.4.6 bounded Portal concurrency');
MERGE INTO CX_REG_FIELD_POLICIES d USING (SELECT 'RFP-DISPLAY-SELF' id,'display_name' fk,'SELF' rc,'REQUIRED' fs,'DISPLAY_NAME' vk,'TRIM' nk FROM DUAL) s ON(d.FIELD_KEY=s.fk AND d.REGISTRATION_CONTEXT=s.rc) WHEN NOT MATCHED THEN INSERT(POLICY_ID,FIELD_KEY,REGISTRATION_CONTEXT,FIELD_STATE,VALIDATOR_KEY,NORMALIZATION_KEY,REASON,UPDATED_BY) VALUES(s.id,s.fk,s.rc,s.fs,s.vk,s.nk,'v4.4.6 default','SYSTEM');
MERGE INTO CX_REG_FIELD_POLICIES d USING (SELECT 'RFP-EMAIL-SELF' id,'email' fk,'SELF' rc,'OPTIONAL' fs,'EMAIL' vk,'EMAIL_LOWER' nk FROM DUAL) s ON(d.FIELD_KEY=s.fk AND d.REGISTRATION_CONTEXT=s.rc) WHEN NOT MATCHED THEN INSERT(POLICY_ID,FIELD_KEY,REGISTRATION_CONTEXT,FIELD_STATE,VALIDATOR_KEY,NORMALIZATION_KEY,REASON,UPDATED_BY) VALUES(s.id,s.fk,s.rc,s.fs,s.vk,s.nk,'v4.4.6 default','SYSTEM');
MERGE INTO CX_REG_FIELD_POLICIES d USING (SELECT 'RFP-MOBILE-SELF' id,'mobile' fk,'SELF' rc,'OPTIONAL' fs,'MOBILE' vk,'E164' nk FROM DUAL) s ON(d.FIELD_KEY=s.fk AND d.REGISTRATION_CONTEXT=s.rc) WHEN NOT MATCHED THEN INSERT(POLICY_ID,FIELD_KEY,REGISTRATION_CONTEXT,FIELD_STATE,VALIDATOR_KEY,NORMALIZATION_KEY,REASON,UPDATED_BY) VALUES(s.id,s.fk,s.rc,s.fs,s.vk,s.nk,'v4.4.6 default','SYSTEM');
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'graph-runtime' k,'CONTROLLED' p,'v4.4.6 evidence gate pending' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'dynamic-graph' k,'CONTROLLED' p,'Requires governed Draft and migration evidence' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'a2a' k,'DISABLED' p,'Enable only after current conformance evidence' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'mcp' k,'CONTROLLED' p,'Protocol metadata is not an authority grant' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'otlp' k,'DISABLED' p,'Enable only after redaction and Collector evidence' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
MERGE INTO CX_GRAPH_CAP_POSTURE d USING (SELECT 'evaluation' k,'CONTROLLED' p,'Recommendations require governed review' l FROM DUAL) s ON(d.CAPABILITY_KEY=s.k) WHEN NOT MATCHED THEN INSERT(CAPABILITY_KEY,POSTURE,LIMITATION_TEXT) VALUES(s.k,s.p,s.l);
COMMIT;
